/** Executable ROM semantics, not a browser integration or runtime capture adapter.
 * Entry: Bank17 ACAF, normal outgoing AA98 result path. Inputs are explicit;
 * this module does not obtain them from emulator RAM or item defaults.
 */
const comparisonFactors = [0,13,26,39,51,65,78,90,102,115,128];
const scaleFactors = [0,128,0,13,26,39,51,65,78,90,102,115,128];
function integer(input, key, max) {
  const value = input[key];
  if (!Number.isInteger(value) || value < 0 || value > max)
    throw new RangeError(`Missing or invalid ${key}`);
  return value;
}
// D654 deliberately drops carry from the 16-bit addition before shifting.
// For value <=32767 this is floor(value*factor/256); keep the actual algorithm
// for larger unsigned values instead of silently extending that formula.
export function fraction(value, factor) {
  if (!Number.isInteger(value) || value<0 || value>65535 ||
      !Number.isInteger(factor) || factor<0 || factor>255) throw new RangeError('fraction input');
  let selected = 0;
  for (let bit=0;bit<8;bit++) {
    if ((factor >>> bit)&1) selected = (selected + value)&65535;
    selected >>>= 1;
  }
  return selected;
}
export function settlePartyAttack(input) {
  const prepared = integer(input,'prepared',65535);
  const defense = integer(input,'defense',65535);
  const comparison70E3 = integer(input,'comparison70E3',255);
  const comparison70E4 = integer(input,'comparison70E4',255);
  const fallbackRandomByte = integer(input,'fallbackRandomByte',255);
  const randomByte = integer(input,'randomByte',255);
  const kind = integer(input,'kind',255);
  const targetScale = integer(input,'targetScale',12);
  const targetStatus = integer(input,'targetStatus',255);
  const shield = integer(input,'shield',255);
  const difference = comparison70E3-comparison70E4;
  const magnitude = Math.min(50,3*Math.abs(difference));
  const comparisonFactor = comparisonFactors[Math.floor(magnitude/5)] + magnitude%5;
  const comparisonDelta = fraction(prepared,comparisonFactor);
  const comparisonAdjusted = (prepared+(difference>=0 ? comparisonDelta : -comparisonDelta))&65535;
  const halfDefense = defense>>>1;
  const intermediate = comparisonAdjusted>halfDefense ? comparisonAdjusted-halfDefense : fallbackRandomByte&3;
  const randomFactor = Math.floor(randomByte*102/256);
  const randomDelta = fraction(intermediate,randomFactor<51 ? randomFactor : randomFactor-51);
  const randomized = (intermediate+(randomFactor<51 ? -randomDelta : randomDelta))&65535;
  let scaled = randomized;
  if (kind===4 || kind===34) {
    if (targetScale===3) scaled = (scaled*2)&65535;
    else if (targetScale!==0) scaled = fraction(scaled,scaleFactors[targetScale]);
  }
  const statusAdjusted = targetStatus&128 ? scaled>>>1 : scaled;
  const final = shield ? Math.floor(statusAdjusted/5) : statusAdjusted;
  return {prepared,comparisonFactor,comparisonDelta,comparisonAdjusted,halfDefense,intermediate,
          randomFactor,randomDelta,randomized,scaled,statusAdjusted,final};
}
